import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long q = Long.parseLong(next());
        long[] amounts = new long[(int) q];
        for (int i = 0; i < amounts.length; i++) amounts[i] = Long.parseLong(next());

        long[] notes = {2000, 500, 200, 100, 50, 20, 10, 5, 2, 1};
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long amount = amounts[i], count = 0;
            for (int k = 0; k < 10; k++) {
                count += amount / notes[k];
                amount %= notes[k];
            }
            out.append(i > 0 ? " " : "").append(count);
        }
        System.out.println(out);
    }
}
